package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	s := next()
	st := make([]byte, 0, len(s)+1)
	for _, c := range s {
		st = append(st, c)
		if m := len(st); m >= 3 && st[m-3] == 'A' && st[m-2] == 'W' && st[m-1] == 'S' {
			st = st[:m-3]
		}
	}
	if len(st) == 0 {
		w.WriteString("-1\n")
	} else {
		w.Write(append(st, '\n'))
	}
